function getSchoolReports(grade,subject,query='',week='Tất cả các tuần'){
 const normalize=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase(),search=normalize(query.trim());
 return schoolReports.filter(r=>String(r.grade)===String(grade)&&(week==='Tất cả các tuần'||r.title===week)).map(report=>({...report,entries:report.entries.filter(e=>e.subject===subject&&(!search||normalize(JSON.stringify(e)+' '+report.title).includes(search)))})).filter(r=>r.entries.length);
}
function renderSchoolReports(){
 const reports=getSchoolReports(state.grade,state.subject,state.search,state.mode);
 if(!reports.length)return `<div class="empty-state"><h3>${state.search?'Chưa tìm thấy nội dung báo bài':'Chưa có báo bài cho lựa chọn này'}</h3><p>${state.search?'Thử từ khóa khác hoặc chọn lại môn học.':'Báo bài sẽ xuất hiện khi được bổ sung cho lớp và môn đã chọn.'}</p></div>`;
 return `<div class="school-reports">${reports.map(report=>`<section aria-labelledby="${report.id}-title" class="school-week"><header class="school-week-heading"><h2 id="${report.id}-title">${escapeHTML(report.title)}</h2><p>Lớp ${escapeHTML(report.grade)} · ${escapeHTML(subjectDisplayName(state.subject))}</p></header><div class="school-lesson-grid">${report.entries.map(entry=>`<article class="school-lesson ${entry.kind?'school-'+entry.kind:''}"><header><time datetime="${entry.date}">${escapeHTML(entry.day)} · ${entry.date.slice(8)}/${entry.date.slice(5,7)}</time><span>Tiết ${escapeHTML(entry.periods)}</span>${entry.kind==='test'?'<strong class="school-kind">Kiểm tra</strong>':entry.kind==='event'?'<strong class="school-kind">Hoạt động</strong>':''}</header><h3>${escapeHTML(entry.title)}</h3>${entry.sections.map(section=>`<div class="school-lesson-section">${section.heading?`<h4>${escapeHTML(section.heading)}</h4>`:''}${section.lines.length?`<ul>${section.lines.map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul>`:''}</div>`).join('')}${(entry.links||[]).map(link=>`<p><a href="${escapeHTML(link.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(link.label)} ↗</a></p>`).join('')}${entry.preparation.length?`<aside class="school-preparation"><h4>Chuẩn bị</h4><ul>${entry.preparation.map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul></aside>`:''}</article>`).join('')}</div></section>`).join('')}</div>`;
}
